// Manual verification infrastructure. Application files must be generated by Acceleo.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const folder=path.resolve(process.argv[2]||'generated/frontend'),requirePhone=process.argv.includes('--require-phone');
const context=vm.createContext({console});
for(const name of ['model.js','demo-store.js'])vm.runInContext(fs.readFileSync(path.join(folder,name),'utf8'),context,{filename:name});
const model=context.FlightModel,Demo=context.FlightDemo;
let checks=0;const check=(condition,message)=>{assert.ok(condition,message);checks++;};
check(model.entities.length===8,'Eight business entities generated');
const html=fs.readFileSync(path.join(folder,'index.html'),'utf8');
for(const e of model.entities)check(html.includes('id="form-'+e.name+'"'),'Generated form for '+e.name);
if(requirePhone){check(model.entities.find(e=>e.name==='Pasajero').fields.some(f=>f.name==='telefono'),'telefono in generated metadata');check(html.includes('name="telefono"'),'telefono in Acceleo-generated HTML input');}
const memory=new Map(),storage={getItem:k=>memory.get(k)||null,setItem:(k,v)=>memory.set(k,v),removeItem:k=>memory.delete(k)};
const clock=()=>new Date('2029-01-01T00:00:00Z');
const app=new Demo(model,{seed:false,clock,storage});
const create=(t,input)=>{for(const f of model.entities.find(e=>e.name===t).fields)if(f.required&&!f.primaryKey&&f.type==='STRING'&&input[f.name]===undefined)input[f.name]='Ejemplo';return app.create(t,input);};
const a=create('Aeropuerto',{codigo:'ORG',nombre:'Origen',ciudad:'Cuenca'}),b=create('Aeropuerto',{codigo:'DST',nombre:'Destino',ciudad:'Quito'});
assert.throws(()=>create('Ruta',{origenId:a.id,destinoId:a.id}),/diferentes/);checks++;
const airline=create('Aerolinea',{codigo:'DEMO',nombre:'Demo Air'});
assert.throws(()=>create('Avion',{matricula:'BAD',capacidad:0,aerolineaId:airline.id}),/mayor que cero/);checks++;
const plane=create('Avion',{matricula:'DEMO-1',capacidad:2,aerolineaId:airline.id});
const route=create('Ruta',{origenId:a.id,destinoId:b.id});
const flight=create('Vuelo',{codigo:'DEMO-001',salida:'2030-01-01T10:00:00Z',llegada:'2030-01-01T11:00:00Z',avionId:plane.id,rutaId:route.id});
check(flight.cuposDisponibles===2,'Initial capacity');
assert.throws(()=>create('Vuelo',{codigo:'OVERLAP',salida:'2030-01-01T10:30:00Z',llegada:'2030-01-01T11:30:00Z',avionId:plane.id,rutaId:route.id}),/incompatible/);checks++;
const passengers=[1,2,3].map(n=>create('Pasajero',{documento:'P'+n,nombreCompleto:'Pasajero '+n,contacto:'p'+n+'@example.invalid'}));
const r1=app.create('Reserva',{vueloId:flight.id,pasajeroId:passengers[0].id});check(r1.numeroAsiento===1,'First seat');
assert.throws(()=>app.reserve({vueloId:flight.id,pasajeroId:passengers[0].id}),/reserva activa/);checks++;
const r2=app.reserve({vueloId:flight.id,pasajeroId:passengers[1].id});check(r2.numeroAsiento===2,'Second seat');
assert.throws(()=>app.reserve({vueloId:flight.id,pasajeroId:passengers[2].id}),/cupos/);checks++;
const ticket=app.issue(r1.id);check(ticket.numeroAsiento===1,'Ticket seat from reservation');check(app.issue(r1.id).id===ticket.id,'Idempotent ticket');
assert.throws(()=>app.cancel(r1.id),/boleto/);checks++;
const cancelled=app.cancel(r2.id);check(cancelled.estado==='CANCELADA'&&cancelled.numeroAsiento===2,'Historical seat preserved');
assert.throws(()=>app.issue(r2.id),/confirmada/);checks++;
const r3=app.reserve({vueloId:flight.id,pasajeroId:passengers[2].id});check(r3.numeroAsiento===2,'Lowest released seat reused');
check(app.get('Vuelo',flight.id).cuposDisponibles===0,'Final capacity');
check(app.all('Reserva').length===3,'History preserved');
const reloaded=new Demo(model,{clock,storage});check(reloaded.all('Reserva').length===3,'Browser storage survives reloading');
check(!app.available().some(v=>v.id===flight.id),'Full flight excluded from availability');
console.log('OK: '+checks+' checks of generated forms, browser demonstration behavior and storage'+(requirePhone?'; telefono propagated to form.':'.'));
